83 |     /**
84 |      * 执行 bash 命令
85 |      *
86 |      * 使用 platform-cmd 模块的跨平台执行函数
87 |      * 自动处理编码差异（Windows GBK / Unix UTF-8）
88 |      * 超时保护通过 timeout 参数传递
89 |      *
90 |      * @param command - 要执行的命令
91 |      * @returns Promise<string> - 执行结果
92 |      */
93 |     private async runCommand(command: string): Promise<string> {
94 |         const normalizedCommand = this.normalizeCommand(command);
95 |         const cdOutput = this.tryHandleCd(normalizedCommand);
96 |         if (cdOutput !== null) return this.truncateOutput( `ERROR: Command failed: ${cdOutput}`);
97 | 
98 |         const result = await execCommandAsync(normalizedCommand, {
99 |             timeout: this.timeout,
100 |             cwd: this.cwd,
101 |         });
102 | 
103 |         if (result.exitCode === 0) {
104 |             return this.truncateOutput(result.stdout || `Command exited successfully`);
105 |         } else {
106 |             // 命令失败时返回 stderr
107 |             return this.truncateOutput(result.stderr || `Command failed with exit code ${result.exitCode}`);
108 |         }
109 |     }
110 | 
111 |     private tryHandleCd(command: string): string | null {
112 |         const platform = getPlatform();
113 |         // 检测复杂命令（包含管道、重定向、命令连接符等），不做 cd 特殊处理
114 |         if (/[|;&<>]|\|\||&&/.test(command)) {
115 |             return null;
116 |         }
117 | 
118 |         const cdMatch = command.match(/^\s*cd(?:\s+\/d)?\s+(.+)\s*$/i);
119 |         if (!cdMatch) return null;
120 | 
121 |         const rawTarget = cdMatch[1]?.trim();
122 |         if (!rawTarget) return null;
123 | 
124 |         const target = rawTarget.replace(/^"(.*)"$/, '$1').replace(/^'(.*)'$/, '$1');
125 |         const resolved = platform === 'windows'
126 |             ? require('path').resolve(this.cwd, target.replace(/\//g, '\\'))
127 |             : require('path').resolve(this.cwd, target);
128 | 
129 |         this.cwd = resolved;
130 |         return this.cwd;
131 |     }
132 | 
133 |     private normalizeCommand(command: string): string {
134 |         if (getPlatform() !== 'windows') return command;
135 | 
136 |         const timeoutMatch = command.match(/^\s*timeout\s+\/t\s+(\d+)\s*$/i);
137 |         if (timeoutMatch) {
138 |             const seconds = Number(timeoutMatch[1]);
139 |             const safeSeconds = Number.isFinite(seconds) ? Math.max(0, seconds) : 0;
140 |             return `powershell -NoProfile -Command "Start-Sleep -Seconds ${safeSeconds}"`;
141 |         }
142 | 
143 |         const mkdirMatch = command.match(/^\s*mkdir\s+(-p|--parents)\s+(.+)\s*$/i);
144 |         if (mkdirMatch) {
145 |             return `mkdir ${mkdirMatch[2]}`;
146 |         }
147 | 
148 |         const { tokens, quoteTypes } = this.tokenize(command);
149 |         const normalizedTokens = tokens.map((token, i) => {
150 |             const quote = quoteTypes[i];
151 |             const original = quote ? `${quote}${token}${quote}` : token;
152 |             if (!token.includes('/')) return original;
153 |             if (token.startsWith('/')) return original;
154 |             if (token.includes('://')) return original;
155 | 
156 |             const looksLikeProjectPath =
157 |                 token.startsWith('./') ||
158 |                 token.startsWith('../') ||
159 |                 token.startsWith('src/') ||
160 |                 token.startsWith('test/') ||
161 |                 token.startsWith('__tests__/') ||
162 |                 /\.(ts|tsx|js|jsx|json|md|txt|log|env)$/i.test(token) ||
163 |                 token.includes('/src/') ||
164 |                 token.includes('/test/') ||
165 |                 token.includes('/__tests__/');
166 | 
167 |             if (!looksLikeProjectPath) return original;
168 | 
169 |             const replaced = token.replace(/\//g, '\\');
170 |             return quote ? `${quote}${replaced}${quote}` : replaced;
171 |         });
172 | 
173 |         return normalizedTokens.join(' ');
174 |     }
175 | 
176 |     private tokenize(command: string): { tokens: string[]; quoteTypes: Array<'"' | "'" | null> } {
177 |         const tokens: string[] = [];
178 |         const quoteTypes: Array<'"' | "'" | null> = [];
179 |         let current = '';
180 |         let quote: '"' | "'" | null = null;
181 | 
182 |         for (let i = 0; i < command.length; i++) {
183 |             const ch = command[i];
184 |             if ((ch === '"' || ch === "'") && quote === null) {
185 |                 quote = ch as '"' | "'";
186 |                 continue;
187 |             }
188 |             if (quote !== null && ch === quote) {
189 |                 tokens.push(current);
190 |                 quoteTypes.push(quote);
191 |                 current = '';
192 |                 quote = null;
193 |                 continue;
194 |             }
195 |             if (quote === null && /\s/.test(ch)) {
196 |                 if (current.length > 0) {
197 |                     tokens.push(current);
198 |                     quoteTypes.push(null);
199 |                     current = '';
200 |                 }
201 |                 continue;
202 |             }
203 |             current += ch;
204 |         }
205 | 
206 |         if (current.length > 0) {
207 |             tokens.push(current);
208 |             quoteTypes.push(quote);
209 |         }
210 | 
211 |         return { tokens, quoteTypes };
212 |     }
213 | 
214 |     private truncateOutput(output: string): string {
215 |         const maxChars = 12000;
216 |         if (output.length <= maxChars) return output;
217 |         return `${output.slice(0, maxChars)}\n... (truncated, ${output.length - maxChars} more chars)`;
218 |     }
219 |  
220 | }
