28 |   async execute({ filePath, replacements }: z.infer<typeof this.schema>): Promise<string> {
29 | 
30 |     const fullPath = path.resolve(process.cwd(), filePath);
31 | 
32 |     if (!fs.existsSync(fullPath)) {
