48 |     // Actually, for line-based replacement without shifting, we can process in any order
49 |     // since we're replacing text within lines, not adding/removing lines
50 | 
51 |     for (const repl of replacements) {
52 |       const { line, oldText, newText } = repl;
53 | 
54 |       if (line < 1 || line > lines.length) {
55 |         results.push(`❌ Line ${line}: out of range (file has ${lines.length} lines)`);
56 |         continue;
57 |       }
58 | 
59 |       const targetLineIdx = line - 1;
