71 | 
72 |     private async withTimeout<T>(promise: Promise<T>, timeoutMs: number, timeoutMessage: string): Promise<T> {
73 |         if (!timeoutMs || timeoutMs <= 0) {
74 |             return promise;
75 |         }
76 | 
77 |         let timeoutId: ReturnType<typeof setTimeout> | undefined;
78 |         const timeoutPromise = new Promise<never>((_, reject) => {
79 |             timeoutId = setTimeout(() => reject(new Error(timeoutMessage)), timeoutMs);
80 |         });
81 | 
82 |         return Promise.race([promise, timeoutPromise]).finally(() => {
83 |             if (timeoutId) {
84 |                 clearTimeout(timeoutId);
85 |             }
86 |         });
87 |     }
88 | 
89 |     private async runWithConcurrency<T, R>(
90 |         items: T[],
91 |         limit: number,
92 |         task: (item: T, index: number) => Promise<R>
93 |     ): Promise<R[]> {
94 |         if (items.length === 0) {
95 |             return [];
96 |         }
97 | 
98 |         if (limit <= 1) {
99 |             const results: R[] = [];
100 |             for (let i = 0; i < items.length; i++) {
101 |                 results.push(await task(items[i], i));
102 |             }
103 |             return results;
104 |         }
105 | 
106 |         const results = new Array<R>(items.length);
107 |         let nextIndex = 0;
108 |         const workerCount = Math.min(limit, items.length);
109 | 
110 |         const workers = Array.from({ length: workerCount }, async () => {
111 |             while (true) {
112 |                 const currentIndex = nextIndex++;
113 |                 if (currentIndex >= items.length) {
114 |                     break;
115 |                 }
116 |                 results[currentIndex] = await task(items[currentIndex], currentIndex);
117 |             }
118 |         });
119 | 
120 |         await Promise.all(workers);
121 |         return results;
122 |     }
