188 |     openBrackets: 0,
189 |     closeBrackets: 0,
190 |     openQuotes: 0,
191 |   };
192 | 
193 |   let inString = false;
194 |   let escapeNext = false;
195 | 
196 |   for (const char of json) {
197 |     if (escapeNext) {
