634 | export function createLoggingMiddleware(source?: string): Middleware {
635 |   return async (context, next) => {
636 |     const startTime = Date.now();
637 |     console.log(`[${source || 'EventBus'}] Event started: ${context.event}`, {
638 |       correlationId: context.metadata.correlationId,
639 |       timestamp: new Date(context.metadata.timestamp).toISOString(),
640 |     });
641 | 
642 |     try {
643 |       await next();
644 |       const duration = Date.now() - startTime;
645 |       console.log(`[${source || 'EventBus'}] Event completed: ${context.event}`, {
646 |         correlationId: context.metadata.correlationId,
647 |         duration: `${duration}ms`,
648 |       });
649 |     } catch (error) {
650 |       const duration = Date.now() - startTime;
651 |       console.error(`[${source || 'EventBus'}] Event failed: ${context.event}`, {
652 |         correlationId: context.metadata.correlationId,
653 |         duration: `${duration}ms`,
654 |         error,
655 |       });
656 |       throw error;
657 |     }
658 |   };
659 | }
