666 | ): Middleware {
667 |   return async (context, next) => {
668 |     try {
669 |       await next();
670 |     } catch (error) {
671 |       if (onError) {
672 |         onError(error instanceof Error ? error : new Error(String(error)), context);
673 |       }
674 |       throw error;
675 |     }
676 |   };
677 | }
